"""Build three self-contained, offline design explorations. No runtime integration."""
from pathlib import Path
import base64
import json
import re

ROOT = Path(__file__).resolve().parent
REPO = ROOT.parents[2]


def data_url(path, mime):
    return f"data:{mime};base64," + base64.b64encode(path.read_bytes()).decode()


manifest = (REPO / 'doris-course/01-real-time-analytics/course.yaml').read_text()
modules = re.findall(r'^    title: (.+)$', manifest, re.M)
assert len(modules) == 10
assets = {
    'logo': data_url(ROOT.parent / 'assets/doris-trimmed.svg', 'image/svg+xml'),
    'logoDark': data_url(ROOT.parent / 'assets/doris-dark-trimmed.svg', 'image/svg+xml'),
    'jupyter': data_url(ROOT.parent / 'assets/jupyter.svg', 'image/svg+xml'),
    'figure': data_url(REPO / 'doris-course/01-real-time-analytics/level1/module01-introduction/images/01-fresh-data-to-analytical-answers.png', 'image/png'),
}
font_css = ''.join(
    f"@font-face{{font-family:'{family}';src:url('{data_url(ROOT.parent / ('assets/' + file), 'font/ttf')}') format('truetype');font-weight:200 800;font-display:swap;}}"
    for family, file in [('Manrope', 'manrope.ttf'), ('Newsreader', 'newsreader.ttf')]
)
font_notices = '\n\n'.join((ROOT.parent / ('assets/' + file)).read_text() for file in ['manrope-OFL.txt', 'newsreader-OFL.txt'])

