SCRIPT = r'''
const ASSETS=__ASSETS__, MODULES=__MODULES__, V='__VARIANT__';
const names={a:'A · 实验手册',b:'B · 工具工作台',c:'C · 阅读优先'};
const routes=[['workspace','个人首页'],['activity','活动入口'],['sign-in','托管登录预览'],['first-login','首次改密'],['mfa','MFA 验证'],['login-error','登录失败'],['course','课程目录'],['lesson','课程阅读'],['terminal','终端引导'],['external','外部工具边界'],['no-activity','无活动'],['ended','活动结束'],['not-ready','环境未就绪'],['denied','无权限'],['expired','会话到期'],['signed-out','退出后'],['help','账号帮助']];
const stateData={
 'no-activity':['No active workshops','There are no workshops available at this entry. Ask your organizer for the activity link and schedule.','Your organizer can confirm when the next activity will open.','Check activities','activity'],
 'ended':['This workshop has ended','Access to this activity is closed. Ask your organizer if another workshop is available.','Files and databases on the workshop environment may have been removed. Signing in again does not restore a retired environment.','Back to activities','activity'],
 'not-ready':['Your environment is not ready','The requested service is currently unavailable. Wait a moment, then try opening it again.','If the service stays unavailable, share your activity and learner ID with your organizer.','Try opening again','external'],
 'denied':['This environment is not assigned to you','You can only open the services assigned to your workshop account.','Return to your workspace to open your own links. If your assignment looks wrong, contact your organizer.','My workspace','workspace'],
 'expired':['Sign in to continue','Your session for this entry has expired. Sign in again to open your assigned services.','For a disconnected notebook, check its kernel and the last cell result before running the cell again.','Sign in again','sign-in'],
 'signed-out':['Signed out of this entry','Close your other course and service tabs, especially if you are using a shared computer.','Other service tabs may still have their own sessions. Signing out does not end the workshop or delete your files.','Back to activities','activity'],
 'help':['Ask your organizer for help','Use the username and temporary password provided for this activity. There is no self-service registration.','If your temporary password has expired or you cannot sign in, ask your organizer for a new temporary password. Never share your password in a screenshot.','Back to sign in','sign-in']
};
let route=new URLSearchParams(location.search).get('view')||'workspace',tool='Notebooks',moduleIndex=0;
if(!routes.some(x=>x[0]===route))route='workspace';
const btn=(text,view,style='primary',extra='')=>`<button class="${style}" data-view="${view}" ${extra}>${text}<span class="arrow" aria-hidden="true">${style==='text-button'?'':'↗'}</span></button>`;
const native=(name)=>`data-view="external" data-tool="${name}"`;
function review(){return `<a class="skip" href="#main">Skip to content</a><div class="review"><strong>${names[V]} / 方向初稿</strong><span class="review-status">示例活动与身份 · 离线预览 · 无真实登录</span><label>查看页面 <select id="view-picker" aria-label="预览页面">${routes.map(([id,label])=>`<option value="${id}" ${route===id?'selected':''}>${label}</option>`).join('')}</select></label><a href="../index.html">对比三版 ↗</a></div>`}
function navigation(cls){return `<nav class="${cls}" aria-label="Workshop navigation">${cls==='side'?'<span class="eyebrow">demo-rta</span>':''}${[['workspace','My workspace'],['course','Course outline'],['terminal','Web Terminal']].map(([id,label])=>`<button class="nav-link" data-view="${id}" ${route===id||id==='course'&&route==='lesson'?'aria-current="page"':''}>${label}</button>`).join('')}${cls==='side'?'<div class="side-bottom">WORKSHOP ACCOUNT<strong>s001</strong>Only your assigned services</div>':''}</nav>`}
function chrome(body,publicPage=false){return `<header class="topbar"><a class="brand" href="?view=activity" data-view="activity"><img src="${V==='b'?ASSETS.logoDark:ASSETS.logo}" alt="Apache Doris"><small>WORKSHOP</small></a>${publicPage?'<span class="eyebrow">Learn by doing</span>':`<div class="identity"><span class="muted mono">demo-rta</span><span class="avatar" aria-hidden="true">S1</span><span class="mono">s001</span><button class="text-button" data-view="signed-out">Sign out of this entry</button></div>`}</header>${V!=='b'&&!publicPage?navigation('nav-horizontal'):''}<div class="${!publicPage?'shell':''}">${V==='b'&&!publicPage?navigation('side'):''}<main class="main" id="main" tabindex="-1">${body}<footer class="footer"><span>Apache Doris Workshop · ${publicPage?'Course environment':'demo-rta / s001'}</span><span>Need help? ${btn('Ask your organizer','help','text-button')}</span></footer></main></div>`}
function breadcrumb(last){return `<div class="breadcrumb"><button data-view="activity">Workshops</button><span aria-hidden="true">/</span><button data-view="workspace">demo-rta</button><span aria-hidden="true">/</span><span>${last}</span></div>`}
function readingHome(){return chrome(`${breadcrumb('My workspace')}<div class="page-head"><div><div class="eyebrow">Your workshop / Real-time Analytics</div><h1>Real-time Analytics<br>with Apache Doris</h1><p>Build fresh analytical datasets, model them for real queries, and interpret distributed execution evidence.</p></div><span class="badge"><span class="dot"></span>Assigned to s001</span></div><section class="reader-preview"><div class="folio"><span>01</span><p>START HERE</p></div><div class="reader-copy"><div class="eyebrow">Build the foundation</div><h2>Introduction to Apache Doris</h2><p>Learn what Apache Doris is and which workloads it is built for, then start a Doris sandbox and load the event dataset that every later module uses.</p><div class="actions">${btn('Read Module 1','lesson','primary','data-module="0"')}${btn('Course outline','course','text-button')}</div></div></section><section class="tools-shelf"><div class="tool-head"><h2>Your tools, when you need them.</h2><span class="muted" style="font-size:12px">Open separately ↗</span></div><div class="shelf-grid"><button class="tool" ${native('Notebooks')}><div><h3 class="icon"><img class="jupyter" src="${ASSETS.jupyter}" alt="Jupyter">Notebooks</h3><p>Run Labs and download your files.</p></div><span class="arrow" aria-hidden="true">↗</span></button><button class="tool" data-view="terminal"><div><h3>Web Terminal</h3><p>Open a shell through JupyterLab.</p></div><span class="arrow" aria-hidden="true">→</span></button><button class="tool" ${native('Doris · single FE')}><div><h3>Doris · single FE</h3><p>Inspect the sandbox started in a Lab.</p></div><span class="arrow" aria-hidden="true">↗</span></button></div><div class="fe-links"><span class="muted">Multi-FE tools</span>${['FE 1','FE 2','FE 3'].map(x=>`<button ${native('Doris · '+x)}>${x} ↗</button>`).join('')}</div></section><section class="environment"><div class="metadata"><span>Activity <strong class="mono">demo-rta</strong></span><span>Learner <strong class="mono">s001</strong></span><span>Profile <strong class="mono">rta-main</strong></span></div></section><aside class="notice"><p><strong>Take your files with you.</strong>Save and download your work before the activity ends. Replacing or removing an environment can remove its files.</p></aside>`)}
function workspace(){if(V==='c')return readingHome();const lead=V==='a'?'Your next step<br>starts here.':V==='c'?'A place to learn by doing.':'My workspace';return chrome(`${breadcrumb('My workspace')}<div class="page-head"><div><div class="eyebrow">Real-time Analytics · Personal environment</div><h1>${lead}</h1><p>Read a lesson, run its Lab, then explore the result in Doris.</p></div><span class="badge"><span class="dot"></span>Assigned to s001</span></div><div class="workspace-grid"><div><section class="start-panel"><div class="eyebrow">${V==='a'?'01 / READ & EXPERIMENT':'START WITH THE COURSE'}</div><h2>Real-time Analytics<br>with Apache Doris</h2><p>Build fresh analytical datasets, model them for real queries, and interpret distributed execution evidence.</p>${btn('Open course','course')}<div class="foot">Begin with Module 1: Introduction to Apache Doris</div><span class="step-index" aria-hidden="true">01</span></section><section class="environment"><h3>Your workshop environment</h3><p>These links belong to the environment assigned to your account.</p><div class="metadata"><span>Activity <strong class="mono">demo-rta</strong></span><span>Learner <strong class="mono">s001</strong></span><span>Profile <strong class="mono">rta-main</strong></span></div></section></div><section class="tools-stack"><div class="tool-head"><h2>Your tools</h2><span class="muted" style="font-size:12px">Open separately ↗</span></div><div class="quick-tools"><button class="tool" data-step="02" ${native('Notebooks')}><div><h3 class="icon"><img class="jupyter" src="${ASSETS.jupyter}" alt="Jupyter">Notebooks</h3><p>Run Labs and download your files.</p></div><span class="arrow" aria-hidden="true">↗</span></button><button class="tool" data-step="03" data-view="terminal"><div><h3>Web Terminal</h3><p>Open a shell through JupyterLab.</p></div><span class="arrow" aria-hidden="true">→</span></button><button class="tool" data-step="04" ${native('Doris · single FE')}><div><h3>Doris · single FE</h3><p>Inspect the sandbox started in a Lab.</p></div><span class="arrow" aria-hidden="true">↗</span></button></div><div class="fe-links"><span class="muted">Multi-FE tools</span>${['FE 1','FE 2','FE 3'].map(x=>`<button ${native('Doris · '+x)}>${x} ↗</button>`).join('')}</div></section></div><aside class="notice"><span aria-hidden="true">↳</span><p><strong>Take your files with you.</strong>Save and download your work before the activity ends. Replacing or removing an environment can remove its files.</p></aside>`)}
function activities(){return chrome(`<div class="activity-panel"><div class="eyebrow">Apache Doris · Hands-on workshops</div><section class="activity-intro"><h1>From a first query<br>to understanding.</h1><p>Choose the activity shared by your organizer. Sign in to reach your own course environment.</p></section><div class="section-title"><h2>Choose your workshop</h2><p class="muted">Example activity</p></div><article class="activity-row"><span class="number" aria-hidden="true">01</span><div><span class="eyebrow">Real-time Analytics</span><h2>Real-time Analytics with Apache Doris</h2><p class="muted mono">demo-rta</p></div>${btn('Sign in to workshop','sign-in')}</article><section class="prep"><div><h3>Have your account ready</h3><p>Your organizer provides a username and temporary password for this activity. Your first sign-in asks you to choose a new password.</p></div><div><h3>Your own environment</h3><p>After sign-in, you will see only your assigned course and service links. You can read lessons and run Labs in your browser.</p></div></section></div>`,true)}
function auth(){const first=route==='first-login',mfa=route==='mfa';return `<main class="auth" id="main"><section class="auth-box" aria-label="Hosted authentication visual preview"><img src="${ASSETS.logo}" alt="Apache Doris"><h1>${first?'Change password':mfa?'Verify your sign-in':'Sign in'}</h1><p>${first?'Set a new password for your workshop account.':mfa?'Enter the code from your authenticator app.':'Sign in with your workshop account.'}</p>${route==='login-error'?'<div class="auth-error" role="alert">Incorrect username or password. Try again.</div>':''}${first?'<label for="new-password">New password</label><input id="new-password" type="password" readonly placeholder="Preview only"><div class="auth-hint">At least 14 characters, including uppercase and lowercase letters, numbers, and symbols.</div><label for="confirm-password">Confirm password</label><input id="confirm-password" type="password" readonly placeholder="Preview only">':mfa?'<label for="code">Authentication code</label><input id="code" type="text" inputmode="numeric" readonly placeholder="6-digit code">':'<label for="username">Username</label><input id="username" type="text" value="s001" readonly autocomplete="off"><label for="password">Password</label><input id="password" type="password" readonly placeholder="Preview only" autocomplete="off">'}${btn(first?'Change password':mfa?'Verify':'Sign in',first||mfa?'workspace':'first-login')}</section></main>`}
function course(){return chrome(`${breadcrumb('Course outline')}<div class="page-head"><div><div class="eyebrow">rta-main / course outline</div><h1>Real-time Analytics<br>with Apache Doris</h1><p>Read a lesson, then open its Lab. Save or download your files in JupyterLab.</p></div>${btn('Open notebooks','external','secondary','data-tool="Notebooks"')}</div><section aria-label="Course modules">${MODULES.map((title,i)=>`${[0,3,7].includes(i)?`<div class="section-title"><h2>${i===0?'Build the foundation':i===3?'Design and query with intent':'Operate for performance and resilience'}</h2><p class="muted">LEVEL ${i===0?'1':i===3?'2':'3'}</p></div>`:''}<article class="module"><span class="module-num">${String(i+1).padStart(2,'0')}</span><div><h3>${title}</h3>${i===0?'<p>Start Doris and build the shared event baseline.</p>':''}</div><div class="module-actions"><button data-view="lesson" data-module="${i}">Read lesson →</button><button ${native('Lab '+(i+1))}>Open Lab ↗</button></div></article>`).join('')}</section><aside class="notice"><p>Module numbering follows the course outline. Choose any lesson to read; your place is not stored by this workshop.</p></aside>`)}
function lesson(){const isFirst=moduleIndex===0;return chrome(`${breadcrumb('Course / Module '+(moduleIndex+1))}<div class="reading-layout"><article class="article"><div class="eyebrow">Level ${moduleIndex<3?'1':moduleIndex<7?'2':'3'} · Module ${String(moduleIndex+1).padStart(2,'0')}</div><h1>${MODULES[moduleIndex]}</h1>${isFirst?`<p class="intro">Learn what Apache Doris is and which workloads it is built for, then start a Doris sandbox and load the event dataset that every later module uses.</p><div class="metadata"><span>Real-time Analytics</span><span>Lesson + Lab</span></div><h2 id="objectives">What you will learn</h2><ul><li>Distinguish OLAP from OLTP by the work that a request does.</li><li>Summarize what the Frontend (FE) and Backend (BE) each do with a query.</li><li>Connect to Doris, load data, and check the result with an aggregation query.</li></ul><h2 id="definition">What is Apache Doris?</h2><p>Apache Doris is an open-source, real-time analytics and search database built on an MPP architecture. It exposes SQL through a MySQL-compatible protocol.</p><h2 id="query">Start with an analytical question</h2><pre><code>SELECT region, COUNT(*) AS purchase_count,
       SUM(revenue) AS total_revenue
FROM events
WHERE event_type = 'purchase'
GROUP BY region;</code></pre><figure><img src="${ASSETS.figure}" alt="Fresh events enter columnar storage, then parallel workers scan, filter and aggregate them into analytical answers."><figcaption>Course illustration: from fresh events to analytical answers.</figcaption></figure>`:`<p class="intro">${MODULES[moduleIndex]} is part of the existing Real-time Analytics course.</p><p>This direction draft demonstrates the reading layout with Module 1. The full lesson content will use the source course Markdown.</p>${btn('Read Module 1 preview','lesson','secondary','data-module="0"')}`}<div class="actions" style="margin-top:30px">${btn('Open Lab '+(moduleIndex+1),'external','primary','data-tool="Lab '+(moduleIndex+1)+'"')}${btn('Course outline','course','secondary')}</div></article><aside class="reading-side"><strong>In this lesson</strong>${isFirst?'<a href="#objectives">What you will learn</a><a href="#definition">What is Apache Doris?</a><a href="#query">An analytical question</a>':''}${btn('Open Lab '+(moduleIndex+1),'external','primary','data-tool="Lab '+(moduleIndex+1)+'"')}<p class="muted" style="margin-top:16px;font-size:12px">Opens separately in JupyterLab. Keep this course tab open.</p>${btn('Back to course','course','text-button')}</aside></div>`)}
function terminal(){return chrome(`${breadcrumb('Web Terminal')}<section class="guide"><div class="eyebrow">Your tools / browser shell</div><h1>Open a terminal<br>on your environment.</h1><p>Use the terminal inside JupyterLab to run commands on your assigned workshop environment.</p><ol class="steps"><li><div><strong>Open JupyterLab</strong><p>Use the button below to open your notebook workspace separately.</p></div></li><li><div><strong>Choose File → New → Terminal</strong><p>This starts a shell on your workshop instance.</p></div></li><li><div><strong>Find an existing terminal</strong><p>Open Running Terminals and Kernels in the JupyterLab sidebar.</p></div></li></ol><div class="actions">${btn('Open JupyterLab','external','primary','data-tool="JupyterLab"')}${btn('My workspace','workspace','secondary')}</div></section>`)}
function external(){return chrome(`${breadcrumb('Your tools')}<section class="state"><div class="external-boundary">设计预览 · 外部工具打开边界，未连接真实服务</div><h1>${tool}</h1><p>In the workshop, this opens your assigned service separately. Keep your course tab open so you can return to the lesson.</p><div class="state-detail"><p>The service belongs to learner <strong class="mono">s001</strong> in activity <strong class="mono">demo-rta</strong>.</p><p>If a Doris sandbox has not been started yet, follow the Lab instructions before opening its web page.</p></div><div class="actions">${btn('Back to course','course')}${btn('My workspace','workspace','secondary')}</div></section>`)}
function state(){const [title,text,detail,label,dest]=stateData[route];return chrome(`${breadcrumb('Workshop access')}<section class="state"><div class="state-number">${{'denied':'ACCESS / 403','not-ready':'SERVICE UNAVAILABLE','expired':'SESSION EXPIRED','signed-out':'ENTRY SIGN-OUT','ended':'ACTIVITY CLOSED','no-activity':'WORKSHOP ENTRY','help':'ACCOUNT HELP'}[route]}</div><h1>${title}</h1><p>${text}</p><div class="state-detail"><p>${detail}</p>${route==='no-activity'?'':'<p>Activity <strong class="mono">demo-rta</strong></p>'}</div><div class="actions">${btn(label,dest)}${route!=='help'?btn('Account help','help','secondary'):''}</div></section>`,['no-activity','ended','signed-out','help'].includes(route))}
function render(focus=false){const hosted=['sign-in','first-login','mfa','login-error'].includes(route);document.title=names[V]+' · '+routes.find(x=>x[0]===route)[1];document.body.dataset.view=route;document.getElementById('app').innerHTML=review()+(hosted?auth():route==='workspace'?workspace():route==='activity'?activities():route==='course'?course():route==='lesson'?lesson():route==='terminal'?terminal():route==='external'?external():state());document.getElementById('view-picker').addEventListener('change',e=>go(e.target.value));document.querySelectorAll('[data-view]').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();if(el.dataset.tool)tool=el.dataset.tool;if(el.dataset.module!==undefined)moduleIndex=Number(el.dataset.module);go(el.dataset.view)}));if(focus)document.querySelector('#main h1')?.setAttribute('tabindex','-1');if(focus)document.querySelector('#main h1')?.focus({preventScroll:true})}
function go(view){route=view;render(true);window.scrollTo(0,0)}
render();
'''

